// ── Complexity analysis ───────────────────────────────────────────────────

const SIMPLE_PATTERNS = [
  /^(hi|hello|hey|yo|sup|howdy)\b/i,
  /^(good\s+)?(morning|afternoon|evening|night)\b/i,
  /^(bye|goodbye|see\s+(ya|you)|later)\b/i,
  /^(yes|no|ok|okay|thanks|thank\s+you|ty)\b/i,
  /^(what's?\s+up|how\s+(are\s+you|r\s+u|goes\s+it))\b/i,
  /^(who\s+(are\s+you|made\s+you))\b/i,
  /\b(say|repeat|echo)\b.{0,30}$/i,
];

const COMPLEX_PATTERNS = [
  /\b(explain\s+in\s+detail|detailed\s+explanation|deep\s+dive|comprehensive)\b/i,
  /\b(compare\s+and\s+contrast|differences?\s+between|similarities?\s+between)\b/i,
  /\b(analyze|analysis|evaluate|assessment)\b/i,
  /\b(code|program|function|algorithm|implement|implementation)\b/i,
  /\b(architecture|system\s+design|design\s+pattern)\b/i,
  /\b(write\s+a|create\s+a|build\s+a|develop\s+a)\s+(program|function|script|app|api|service)\b/i,
  /\b(debug|refactor|optimize|performance)\b.*\b(code|app|function|query|system)\b/i,
  /\b(mathematical|proof|theorem|derive|equation|formula)\b/i,
  /\b(essay|article|report|documentation|tutorial)\b/i,
  /\b(research|thesis|dissertation|academic|scholarly)\b/i,
  /\b(migration|migrate|deploy|deployment|ci\/cd|pipeline)\b/i,
  /\b(security|vulnerability|exploit|encryption|authentication)\b/i,
  /\b(microservices?|kubernetes|docker|container|orchestration)\b/i,
  /\b(machine\s+learning|deep\s+learning|neural|nlp|transformer|llm)\b/i,
  /^.{200,}$/s,
];

function classifyComplexity(message) {
  if (!message || typeof message !== 'string') return { label: 'simple', score: 0 };

  const text = message.trim();
  const wordCount = text.split(/\s+/).length;

  if (wordCount <= 3 && SIMPLE_PATTERNS.some(p => p.test(text))) {
    return { label: 'simple', score: 1 };
  }

  if (COMPLEX_PATTERNS.some(p => p.test(text)) || wordCount > 50) {
    return { label: 'complex', score: 3 };
  }

  if (wordCount > 15 || text.includes('?') && wordCount > 8) {
    return { label: 'medium', score: 2 };
  }

  return { label: 'simple', score: 1 };
}

// ── Chat (POST /v1/chat) ──────────────────────────────────────────────────

async function chatHandler(request) {
  try {
    if (!OPENROUTER_API_KEY) {
      return jsonResponse({
        response: '',
        session_id: 'default',
        type: 'error',
      }, 503);
    }

    const body = await request.json();
    const { message, session_id = 'default', timezone = '', location = '', messages: history = [] } = body;

    if (!message) {
      return jsonResponse({
        response: '',
        session_id,
        type: 'error',
      }, 400);
    }

    const messages = await buildMessagesWithSearch(message, session_id, timezone, location, DEFAULT_SYSTEM_PROMPT, history);

    const complexity = classifyComplexity(message);
    const opts = complexity.label === 'simple'
      ? { max_tokens: 512, temperature: 0.5 }
      : complexity.label === 'complex'
        ? { max_tokens: 8192, temperature: 0.8 }
        : { max_tokens: 2048, temperature: 0.7 };

    const resp = await callOpenRouter(messages, opts);
    const data = await resp.json();
    const content = sanitizeText(data?.choices?.[0]?.message?.content || '');

    if (!content) {
      return jsonResponse({
        response: '',
        session_id,
        type: 'error',
      }, 502);
    }

    const complexityScore = complexity.score;
    const complexityLabel = complexity.label;

    return jsonResponse({
      response: content,
      session_id,
      type: 'chat',
      image_data: '',
      image_type: '',
      file_data: '',
      file_name: '',
      file_type: '',
      complexity: complexityScore,
      complexity_label: complexityLabel,
    });
  } catch (e) {
    return jsonResponse({
      response: '',
      session_id: 'default',
      type: 'error',
      debug: e?.message || 'unknown',
      image_data: '',
      image_type: '',
      file_data: '',
      file_name: '',
      file_type: '',
      complexity: 0,
      complexity_label: 'simple',
    });
  }
}

// ── Chat Stream (POST /v1/chat/stream) ────────────────────────────────────

async function chatStreamHandler(request) {
  try {
    const body = await request.json();
    const { message, session_id = 'default', timezone = '', location = '', messages: history = [] } = body;

    if (!message) {
      return jsonResponse({ error: 'No message provided' }, 400);
    }

    const messages = await buildMessagesWithSearch(message, session_id, timezone, location, DEFAULT_SYSTEM_PROMPT, history);

    const complexity = classifyComplexity(message);
    const opts = complexity.label === 'simple'
      ? { stream: true, max_tokens: 512, temperature: 0.5 }
      : complexity.label === 'complex'
        ? { stream: true, max_tokens: 8192, temperature: 0.8 }
        : { stream: true, max_tokens: 2048, temperature: 0.7 };

    const resp = await callOpenRouter(messages, opts);

    const { readable, writable } = new TransformStream();
    const writer = writable.getWriter();
    const encoder = new TextEncoder();

    (async () => {
      try {
        const reader = resp.body.getReader();
        const decoder = new TextDecoder();
        let buffer = '';

        while (true) {
          const { done, value } = await reader.read();
          if (done) break;

          buffer += decoder.decode(value, { stream: true });
          const lines = buffer.split('\n');
          buffer = lines.pop() || '';

          for (const line of lines) {
            if (line.startsWith('data: ')) {
              const chunk = line.slice(6).trim();
              if (chunk === '[DONE]') continue;
              try {
                const parsed = JSON.parse(chunk);
                const delta = parsed?.choices?.[0]?.delta;
                const content = delta?.content;
                const reasoning = delta?.reasoning || parsed?.choices?.[0]?.reasoning;
                if (content || reasoning) {
                  await writer.write(encoder.encode(`data: ${JSON.stringify({ content: content || '', reasoning: reasoning || '' })}\n\n`));
                }
              } catch (_) {}
            }
          }
        }

        await writer.write(encoder.encode(`data: ${JSON.stringify({ done: true })}\n\n`));
      } catch (e) {
        await writer.write(encoder.encode(`data: ${JSON.stringify({ error: 'Stream error occurred', done: true })}\n\n`));
      } finally {
        await writer.close();
      }
    })();

    return new Response(readable, {
      headers: {
        'Content-Type': 'text/event-stream',
        'Cache-Control': 'no-cache',
        Connection: 'keep-alive',
        'X-Accel-Buffering': 'no',
        'Access-Control-Allow-Origin': '*',
      },
    });
  } catch (e) {
    return jsonResponse({ error: 'Failed to start stream' }, 500);
  }
}

// ── Supported image MIME types ─────────────────────────────────────────────

const SUPPORTED_IMAGE_TYPES = new Set([
  'image/jpeg', 'image/png', 'image/gif', 'image/webp',
  'image/bmp', 'image/tiff', 'image/svg+xml',
  'image/avif', 'image/x-icon',
]);

function normalizeImageMime(mimeType, fileName) {
  if (mimeType && SUPPORTED_IMAGE_TYPES.has(mimeType)) return mimeType;
  const ext = (fileName || '').split('.').pop()?.toLowerCase();
  const extMap = {
    jpg: 'image/jpeg', jpeg: 'image/jpeg', png: 'image/png',
    gif: 'image/gif', webp: 'image/webp', bmp: 'image/bmp',
    tiff: 'image/tiff', tif: 'image/tiff', svg: 'image/svg+xml',
    avif: 'image/avif', ico: 'image/x-icon',
  };
  if (ext && extMap[ext]) return extMap[ext];
  return 'image/jpeg';
}

function isImageMimeType(mimeType) {
  return (mimeType || '').startsWith('image/');
}

async function constructEditPrompt(userRequest, originalDescription) {
  const subject = originalDescription && originalDescription.length > 20
    ? originalDescription
    : 'the main subject of the uploaded image';

  try {
    const llmMessages = [
      { role: 'system', content: 'You generate MINIMAL image edit prompts. CRITICAL: ONLY describe what changed — NEVER re-describe the original subject. Begin with "Original image of [brief subject], now with" followed by ONLY the changes. Keep it under 30 words. No text, no typography in the image.' },
      { role: 'user', content: `Original: "${subject}"\nChange only: "${userRequest}"\n\nGenerate ONE short sentence starting with "Original image of" then ONLY describing what changed.` },
    ];
    const resp = await callOpenRouter(llmMessages, { model: OPENROUTER_MODEL, stream: false, max_tokens: 200, temperature: 0.1 });
    const data = await resp.json();
    const generated = data?.choices?.[0]?.message?.content?.trim();
    if (generated && generated.length > 15 && isValidImagePrompt(generated, userRequest)) {
      return generated;
    }
  } catch {}

  const cleanRequest = userRequest
    .replace(/^(edit|modify|redesign|transform|enhance|improve|recreate|reimagine|turn|convert|change|make|create|generate|draw|paint|sketch|render)\s+(this|it|the|my|that)\s+(image|picture|photo|pic)?\s*/i, '')
    .replace(/\b(please|pls|kindly|i want|i need|can you|could you|would you)\b/gi, '')
    .trim();

  if (cleanRequest && cleanRequest.length > 5) {
    return `Original image of ${subject}, now with ${cleanRequest}`;
  }
  return `Original image of ${subject}`;
}

// Responses are now LLM-generated — no hardcoded templates

function isValidImagePrompt(text, originalUserText) {
  if (!text || text.length < 10) return false;
  const trimmed = text.trim();
  // Allow PROMPT: prefix format
  const processed = trimmed.replace(/^PROMPT:\s*/i, '');
  // Reject if contains code fences
  if (/```[\s\S]*```/.test(processed)) return false;
  // Reject if contains JSON-like content (starts with { and has quoted keys)
  if (/^[\s]*\{[\s\S]*"[\w]+"[\s]*:/.test(processed)) return false;
  // Reject if the text is just the user's original message repeated verbatim
  if (originalUserText && processed.toLowerCase() === originalUserText.trim().toLowerCase()) return false;
  // Reject conversational text that starts with filler words typical of LLM chat
  if (/^(sure|okay|ok|here('s| is)|i('ve| have)|certainly|of course|absolutely|the user|i will|i can|to edit|to transform|based on|according to)/i.test(processed)) return false;
  // Reject if the prompt sounds like a command to an AI rather than an image description
  if (/^(edit|modify|transform|change|turn|convert|make|create|generate|redesign|enhance|improve)\s+(this|the|it|my|that)/i.test(processed)) return false;
  return true;
}

async function pollinationsImage(prompt, retries = 2) {
  const seed = Math.floor(Math.random() * 1000000);
  const negative = 'text, letters, words, signature, caption, writing, typography, deformed, distorted, blurry, low quality';

  // Use text-to-image with a comprehensive prompt that describes everything needed
  // The prompt should already contain full details of what to preserve + what to change
  const encodedPrompt = encodeURIComponent(prompt);
  const encodedNegative = encodeURIComponent(negative);
  const sizes = ['1024x1024', '768x768', '512x512'];
  const models = ['flux', 'flux', 'flux'];

  for (let i = 0; i < sizes.length; i++) {
    for (let r = 0; r <= retries; r++) {
      try {
        const url = `https://image.pollinations.ai/prompt/${encodedPrompt}?width=${sizes[i].split('x')[0]}&height=${sizes[i].split('x')[1]}&model=${models[i]}&negative=${encodedNegative}&seed=${seed + i + r}`;
        const resp = await fetch(url);
        if (!resp.ok) continue;
        const buf = await resp.arrayBuffer();
        if (buf && buf.byteLength > 500) return buf;
      } catch {}
    }
  }
  throw new Error('Image generation failed');
}

