    const textExts = ['txt', 'md', 'py', 'js', 'ts', 'html', 'css', 'json', 'xml', 'yaml', 'yml', 'csv', 'dart', 'go', 'rs', 'rb', 'php', 'java', 'cpp', 'c', 'h', 'hpp', 'swift', 'kt', 'sh', 'bat', 'ps1', 'sql', 'log', 'ini', 'cfg', 'toml', 'rtf'];

